class Solution {
  private int count;

  private int dfs(TreeNode node) {
    if (node == null) return 0;
    int best = Math.max(dfs(node.left), dfs(node.right));
    if (node.val >= best) count++;
    return Math.max(best, node.val);
  }

  public int countDominantNodes(TreeNode root) {
    count = 0;
    dfs(root);
    return count;
  }
}
